#include <bits/stdc++.h>
#define endl '\n'

using namespace std;

using ll = long long;

const ll N = 5005;

int n, d[N];
bool ans[N][N];
ll m;

void init() {}

void solve()
{
	cin >> n >> m;
	for (int i = 1; i <= n; ++i)
		d[i] = n - i;
	for (int i = 1; i <= n; ++i)
	{
		for (int j = n, t; j > i; --j)
		{
			t = d[i] - d[j] - 1;
			if (t <= 0 || t > m)
				continue;
			ans[j][i] = 1;
			--d[i], ++d[j];
			m -= t;
		}
	}
	if (m)
	{
		cout << "No" << endl;
		return;
	}
	cout << "Yes" << endl;
	for (int i = 2; i <= n; ++i)
	{
		for (int j = 1; j < i; ++j)
			cout << ans[i][j];
		cout << endl;
	}
	// for (int i = 1; i <= n; ++i)
	// 	cerr << d[i] << " \n"[i == n];
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);
	int _ = 1;
	cin >> _;
	init();
	while (_--)
		solve();
	return 0;
}

